/**
 * Curated Composio tool registry for `app_action` workflow steps — the
 * contract between the AI builder and the engine. If a slug isn't here, the
 * builder may not emit it and the engine will not execute it.
 *
 * Social posting is deliberately NOT in this registry: it's the dedicated
 * `social_post` step, which goes through socialProvider.post() so multi-call
 * platforms (LinkedIn author, Facebook page, Instagram container) work.
 */

export interface ToolSpec {
  /** Composio toolkit slug (used for the connection pre-check). */
  app: string;
  kind: "read" | "write";
  /** Externally visible / affects other people → builder should consider approval. */
  external: boolean;
  required: string[];
  desc: string;
  argHint: string;
  /** Composio toolkit version captured when this action was selected. */
  version?: string;
  /** JSON Schema of expected inputs if available. */
  inputSchema?: Record<string, unknown>;
  /** JSON Schema of action outputs if available. */
  outputSchema?: Record<string, unknown>;
  /**
   * Constants filled in at run time when the author left the argument blank.
   *
   * This is where an ARRAY argument belongs. The step's Arguments editor is a
   * key/value grid of text inputs (inspector.tsx), so an array living in the
   * saved graph renders as JSON and turns into a plain string the moment
   * someone edits that row — a silent corruption with no error anywhere.
   */
  defaults?: Record<string, unknown>;
  /**
   * Arguments the WORKSPACE has already answered, resolved server-side.
   *
   * Markers only — the lookups live in steps.ts. This module has no imports on
   * purpose: it is pulled into the client bundle through blocks.ts by the
   * canvas, the inspector and the step picker, so reaching a server-only
   * module (Supabase, the brand profile) from here would break the production
   * build while `tsc --noEmit` stayed green.
   */
  autofill?: Record<string, AutofillSource>;
  /**
   * Constraints the PROVIDER imposes that no amount of correct setup removes —
   * WhatsApp's 24-hour reply window, LinkedIn having no analytics endpoint.
   *
   * These already existed inside `desc`, which is written for the builder LLM
   * and is never shown to a person. So the rule that decides whether the
   * automation can do what was asked lived only in the prompt, and the user met
   * it as a provider error on a live run. Stated separately, `limitations()`
   * can put it in front of them while they are still building. One short
   * sentence each: this is read at a glance, not studied.
   */
  limits?: string[];
}

/**
 * A value the workspace has saved once and should never have to paste again.
 *
 * Deliberately narrow: autofill reads what is already stored, it does not go
 * discover values with an extra API call. WhatsApp's sender id, for instance,
 * stays an ordinary required argument — there is no saved home for it, and a
 * business with several numbers would need us to guess which one speaks.
 */
export type AutofillSource = "meta_ad_account";

/**
 * Apps that have NO Composio toolkit (verified against the live v3 catalog).
 * They connect instantly without OAuth and every tool call runs simulated —
 * the standard ZidaneAI degradation so the workflow is still fully buildable,
 * testable, and demonstrable end to end.
 */
export const SIMULATED_APPS = new Set(["googlebusinessprofile"]);

/**
 * The fastest a polled trigger can possibly be checked.
 *
 * Not a policy — a fact about the machine. `deploy/systemd/zidane-cron.timer`
 * fires the beat every 15 minutes and each workspace then decides whether it is
 * due, so a trigger asking for 5 gets 15 and a card promising "every 5 min"
 * would be describing something that cannot happen. The shipped templates
 * already bottom out at exactly 15.
 */
export const MIN_POLL_MINUTES = 15;

/**
 * How often this trigger is REALLY checked, in minutes.
 *
 * One definition, because there were four: `sweep.ts` (the behaviour),
 * `blocks.ts` (the card's "checks hourly" suffix), `limitations.ts` (the "runs
 * up to N late" line) and `display.ts` each wrote their own
 * `Number(x) > 0 ? x : 60`. They agreed only by coincidence, which is exactly
 * the shape that lets a card advertise a cadence the poller does not use.
 *
 * An absent, zero or unparseable value means "never set", which is an hour —
 * distinct from a value set too low, which is raised to the floor.
 */
export function pollMinutes(step: Record<string, unknown>): number {
  const raw = Number(step.interval_minutes);
  const wanted = Number.isFinite(raw) && raw > 0 ? raw : 60;
  return Math.max(MIN_POLL_MINUTES, wanted);
}

/** Display labels for apps that appear in workflows (fallback: title-case slug). */
export const APP_LABELS: Record<string, string> = {
  vikunja: "Vikunja",
  googlebusinessprofile: "Google Business Profile",
  gmail: "Gmail",
  notion: "Notion",
  googlesheets: "Google Sheets",
  google_search_console: "Search Console",
  google_analytics: "Google Analytics",
  googleads: "Google Ads",
  youtube: "YouTube",
  github: "GitHub",
  googlecalendar: "Google Calendar",
  slack: "Slack",
  shopify: "Shopify",
  linkedin: "LinkedIn",
  linear: "Linear",
  metaads: "Meta Ads",
  whatsapp: "WhatsApp",
  googledrive: "Google Drive",
  airtable: "Airtable",
  telegram: "Telegram",
  hubspot: "HubSpot",
  firecrawl: "Firecrawl",
};

export function appLabel(app: string): string {
  return APP_LABELS[app] ?? app.charAt(0).toUpperCase() + app.slice(1);
}

// ---------------------------------------------------------------------------
// App-event triggers — Relay-style "when X happens in <app>" workflow starts.
// The poller (and the Test button) materializes events; each event's fields
// are exposed to later steps as {{steps.<trigger_id>.event.<field>}}.
// ---------------------------------------------------------------------------

/**
 * A setting that tells the poller WHAT to watch — the GitHub repo, the Slack
 * channel, the calendar. Stored flat on the trigger step as `watch_<key>` so
 * the inspector renders it with the ordinary field machinery, and passed to
 * the poll tool by `pollArgs`.
 *
 * Without these, every poll ran with no arguments at all, so any event whose
 * provider needs a target simply failed — which is why the GitHub trigger
 * answered 404 every time it was tried.
 */
export interface TriggerWatchField {
  key: string;
  label: string;
  hint?: string;
  placeholder?: string;
  /** Blank blocks switching the automation on (see `missingSetup`). */
  required?: boolean;
  /** Pre-filled when the block is inserted. */
  default?: string;
}

export interface TriggerSpec {
  app: string;
  desc: string;
  /** Fields every event exposes (name → short description for the builder). */
  event: Record<string, string>;
  /** Registry READ tool the scheduler polls for new items (absent = simulated only). */
  pollTool?: string;
  /** What the user must tell us in order to poll (repo, channel, calendar…). */
  watch?: TriggerWatchField[];
  /** Arguments for `pollTool`, built from the step's `watch_*` values. */
  pollArgs?: (watch: Record<string, string>) => Record<string, unknown>;
  /** Map one polled provider record to the trigger's event shape. */
  mapRecord?: (rec: Record<string, unknown>) => Record<string, unknown>;
  /** How this trigger runs in real time, when Composio offers a watch for it. */
  realtime?: RealtimeSpec;
  /** A realistic event used by the Test button and simulated polls. */
  sample: Record<string, unknown>;
}

/**
 * The push version of a trigger.
 *
 * `slugs` is a PREFERENCE LIST, not an answer. Composio names its trigger
 * types per toolkit and renames them; hardcoding one would mean shipping an
 * automation that 400s the moment somebody switches it on. The enable path
 * resolves these against the live catalog and falls back to polling — with a
 * reason on the workflow — when none of them exists.
 */
export interface RealtimeSpec {
  slugs: string[];
  /**
   * Desired instance config from the step's watch_* values. Filtered against
   * the trigger type's own schema before it is sent, so an extra key here is
   * harmless and a missing one is reported rather than guessed at.
   */
  config?: (watch: Record<string, string>) => Record<string, unknown>;
  /**
   * `watch_*` keys the trigger TYPE declares required, so real time is
   * unreachable without them.
   *
   * The authoritative list lives in Composio's catalog and is only readable
   * server-side, at enable time — far too late to tell someone while they are
   * choosing a trigger. Mirroring it here lets the editor say "fill this in or
   * this runs on a schedule" up front. Being wrong is cheap in one direction
   * only: a stale entry over-warns, whereas a missing one is the silent
   * downgrade this is here to prevent.
   */
  needs?: string[];
  /**
   * Map a PUSHED payload to the trigger's event shape. Push payloads are the
   * provider's own webhook body and are shaped differently from the poll
   * listing, so this is not `mapRecord` — though it usually delegates to it
   * once the interesting object has been dug out.
   */
  mapEvent?: (data: Record<string, unknown>) => Record<string, unknown>;
}

/** A nested string field (`start.dateTime`) off a loosely-typed record. */
function nested(rec: Record<string, unknown>, key: string, ...fields: string[]): string {
  const inner = rec[key];
  if (!inner || typeof inner !== "object") return "";
  for (const f of fields) {
    const v = (inner as Record<string, unknown>)[f];
    if (v != null && String(v) !== "") return String(v);
  }
  return "";
}

/** Dig out the first plausible record from a push payload wrapper. */
function unwrap(data: Record<string, unknown>, ...keys: string[]): Record<string, unknown> {
  for (const key of keys) {
    const value = data[key];
    if (value && typeof value === "object" && !Array.isArray(value)) {
      return value as Record<string, unknown>;
    }
  }
  return data;
}

/**
 * A value that LOOKS filled in but names nothing real.
 *
 * The builder LLM used to be shown a catalog of angle-bracket examples — every
 * `argHint` below once read like `'{"owner": "<org>", "repo": "<repo>"}'`. When
 * the user's request never named a repository, the model copied the example
 * through as if it were an answer. Every guard downstream tested only for
 * BLANK, so a step holding `watch_owner: "<owner>"` passed setup validation,
 * passed the enable gate, and became an hourly GitHub 404 on a live automation.
 *
 * The catalog no longer ships stand-ins and the prompt forbids inventing one,
 * but neither is a guarantee about a language model, and graphs saved before
 * both changes are still on disk. So this stays: the shape is what is refused,
 * not the one catalog that happened to teach it.
 *
 * Deliberately NARROW, because a false positive blanks a value somebody meant.
 * Only a whole value that is nothing but a stand-in counts: a string that
 * merely CONTAINS angle brackets (an AI-drafted email body holding `<b>`) is
 * left alone, and so are real targets like `vercel`, `next.js`, `primary`,
 * `#general` and any genuine address.
 */
// Only strings that cannot be anybody's answer. "todo"/"tbd"/"n/a" were here and
// had to come out: a Google Sheets tab named TODO, a repo called `todo`, a
// #todo channel and a "TBD" event title are all real, and blanking them is
// exactly the false positive this guard must never produce.
const PLACEHOLDER_WORDS = new Set(["...", "\u2026", "a@b.com"]);

export function isPlaceholder(value: unknown): boolean {
  if (value == null) return false;
  const v = String(value).trim();
  if (!v) return false;
  // The whole value is a stand-in: <owner>, <org>, <page id>, <channel id or #name>.
  if (/^<[^<>]*>$/.test(v)) return true;
  if (PLACEHOLDER_WORDS.has(v.toLowerCase())) return true;
  // RFC 2606 reserves these precisely so they can never be a real inbox.
  if (/@example\.(com|org|net)$/i.test(v)) return true;
  return false;
}

/** The `watch_*` values set on a trigger step, keyed without the prefix. */
export function watchValues(step: Record<string, unknown>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(step)) {
    if (!k.startsWith("watch_") || v == null) continue;
    const value = String(v).trim();
    // A placeholder is DROPPED here rather than passed on, so that ONE test
    // covers every consumer: missingWatch, setupGaps, the enable gate, the
    // sweep's pre-poll guard, pollArgs, realtime.config and the trigger
    // summary all ask this function what the user actually set.
    if (!value || isPlaceholder(value)) continue;
    out[k.slice("watch_".length)] = value;
  }
  return out;
}

/** Required watch fields the user still has to fill in for this trigger. */
export function missingWatch(step: Record<string, unknown>): TriggerWatchField[] {
  const spec = getTrigger(String(step.event ?? ""));
  if (!spec?.watch) return [];
  const set = watchValues(step);
  return spec.watch.filter((w) => w.required && !set[w.key]);
}

function str(v: unknown): string {
  return v == null ? "" : String(v);
}

